faq_1	{"id": "faq_1", "draft": {"page": "competitive", "answer": "Only depending on the coach. At minimum, there is a fall season and two tournaments. Some coaches play indoor/futsal in winter; spring is optional.", "question": "Is comp year-round?"}, "order": 0, "status": "published", "version": 1, "createdAt": "2026-11-09T14:53:20.127Z", "createdBy": "seed", "published": {"page": "competitive", "answer": "Only depending on the coach. At minimum, there is a fall season and two tournaments. Some coaches play indoor/futsal in winter; spring is optional.", "question": "Is comp year-round?"}, "updatedAt": "2026-11-09T14:53:20.127Z", "updatedBy": "seed", "collection": "faqs", "publishedVersion": 1}
faq_2	{"id": "faq_2", "draft": {"page": "competitive", "answer": "Mostly locally: Sacramento, Folsom and El Dorado Hills, with some games in Roseville, Yuba City, Chico and Truckee. Not every division has teams in the farther locations. League play can extend south to Modesto; teams typically also enter at least one overnight travel tournament.", "question": "How far do we travel?"}, "order": 1, "status": "published", "version": 1, "createdAt": "2026-11-09T14:53:20.127Z", "createdBy": "seed", "published": {"page": "competitive", "answer": "Mostly locally: Sacramento, Folsom and El Dorado Hills, with some games in Roseville, Yuba City, Chico and Truckee. Not every division has teams in the farther locations. League play can extend south to Modesto; teams typically also enter at least one overnight travel tournament.", "question": "How far do we travel?"}, "updatedAt": "2026-11-09T14:53:20.127Z", "updatedBy": "seed", "collection": "faqs", "publishedVersion": 1}
faq_3	{"id": "faq_3", "draft": {"page": "competitive", "answer": "Players must attend tryouts, held in January, February or May depending on age group. A second team may form depending on tryout numbers and coach availability.", "question": "How do tryouts work?"}, "order": 2, "status": "published", "version": 1, "createdAt": "2026-11-09T14:53:20.127Z", "createdBy": "seed", "published": {"page": "competitive", "answer": "Players must attend tryouts, held in January, February or May depending on age group. A second team may form depending on tryout numbers and coach availability.", "question": "How do tryouts work?"}, "updatedAt": "2026-11-09T14:53:20.127Z", "updatedBy": "seed", "collection": "faqs", "publishedVersion": 1}
faq_4	{"id": "faq_4", "draft": {"page": "competitive", "answer": "Playing formats are 7v7 at U9, 9v9 at U11, and 11v11 at U13 and older.", "question": "What is the team size by age?"}, "order": 3, "status": "published", "version": 1, "createdAt": "2026-11-09T14:53:20.127Z", "createdBy": "seed", "published": {"page": "competitive", "answer": "Playing formats are 7v7 at U9, 9v9 at U11, and 11v11 at U13 and older.", "question": "What is the team size by age?"}, "updatedAt": "2026-11-09T14:53:20.127Z", "updatedBy": "seed", "collection": "faqs", "publishedVersion": 1}
faq_5	{"id": "faq_5", "draft": {"page": "competitive", "answer": "The U.S. Soccer Learning Center introduction course is free. Grassroots courses are 2 hours and $25; the club reimburses the course fee once the certificate is received.", "question": "Is coach education reimbursed?"}, "order": 4, "status": "published", "version": 1, "createdAt": "2026-11-09T14:53:20.127Z", "createdBy": "seed", "published": {"page": "competitive", "answer": "The U.S. Soccer Learning Center introduction course is free. Grassroots courses are 2 hours and $25; the club reimburses the course fee once the certificate is received.", "question": "Is coach education reimbursed?"}, "updatedAt": "2026-11-09T14:53:20.127Z", "updatedBy": "seed", "collection": "faqs", "publishedVersion": 1}
