rev_01k70cpabn_ml9sdf	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cpabn_ml9sdf", "data": {"cta": {"text": "Not sure which program fits, or need help with registration? Our communications director will point you in the right direction.", "title": "We’re here to help", "buttons": [{"_key": "15f6dc59", "href": "mailto:communicationsdirector@prospector.org", "label": "Email the club", "external": false}, {"_key": "26e52855", "href": "/resources", "label": "Resources", "external": false}], "eyebrow": "Questions?"}, "band": {"lead": "PSC is a non-profit, volunteer-run club — from the board members who run it to the volunteer head coaches on the sideline.", "image": {"alt": "", "mediaId": "med_about"}, "stats": [{"_key": "968c17a8", "label": "volunteer-run, non-profit club", "value": "100%"}, {"_key": "d4671c45", "label": "every age, from first kicks to seniors", "value": "U6–U19"}, {"_key": "e866d3ca", "label": "competitive teams for Fall 2026 / Spring 2027", "value": "11"}, {"_key": "b4b32821", "label": "communities: Cameron Park, Shingle Springs & Rescue", "value": "3"}], "title": "Run by volunteers.\\nPowered by Gold Country.", "eyebrow": "Built by neighbors"}, "hero": {"lead": "A non-profit, volunteer-run club where kids from U6 to U19 learn the game, grow as teammates, and fall in love with Saturday mornings in the foothills.", "image": {"alt": "Youth soccer players racing for the ball at golden hour on a foothill field ringed by oak trees", "mediaId": "med_hero"}, "pills": [{"_key": "00fd783b", "text": "Non-profit · 100% volunteer-run"}, {"_key": "6116b6e0", "text": "Ages U6–U19"}, {"_key": "13355024", "text": "Rec & Comp"}], "title": "Gold Country’s home for *youth soccer*", "eyebrow": "Cameron Park · Shingle Springs · Rescue", "primaryCta": {"href": "/recreational", "label": "Recreational program", "external": false}, "secondaryCta": {"href": "/competitive", "label": "Competitive teams", "external": false}}, "meta": {"title": "Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_hero_jpg"}, "description": "Prospector Soccer Club — non-profit, volunteer-run youth soccer for Cameron Park, Shingle Springs and Rescue, California. Recreational U6–U19 and competitive U9–U19."}, "season": {"bands": [{"to": 100, "_key": "0a4a16ea", "from": 25, "kind": "comp"}, {"to": 88, "_key": "1b3db2c6", "from": 54, "kind": "rec"}], "marks": [{"_key": "24ad4c65", "label": "Comp tryouts", "position": 8.33}, {"_key": "e3c4f8e9", "label": "Rec registration", "position": 25}, {"_key": "c38050be", "label": "May tryouts", "position": 37.5}, {"_key": "108a7be4", "label": "Rec practices", "position": 54}, {"_key": "170da577", "label": "Fall games", "position": 64}, {"_key": "45c43bf8", "label": "All-stars", "position": 87.5}], "title": "The PSC year", "legend": [{"_key": "70aaa4f2", "label": "Recreational season (from mid-July)", "swatch": "var(--blue-600)"}, {"_key": "7c17a805", "label": "Competitive season (Apr – Dec)", "swatch": "rgb(11 42 91 / .2)"}, {"_key": "bc24f7bd", "label": "Today", "swatch": "var(--gold-500)"}], "phases": [{"_key": "phase000", "label": "Competitive tryouts (by age group)", "toMonth": 2, "fromMonth": 1}, {"_key": "phase001", "label": "Spring season options for comp teams", "toMonth": 3, "fromMonth": 3}, {"_key": "phase002", "label": "Rec registration is open (Apr 1 – Jun 15)", "toMonth": 6, "fromMonth": 4}, {"_key": "phase003", "label": "Rec practices kick off mid-July", "toMonth": 7, "fromMonth": 7}, {"_key": "phase004", "label": "Fall season is underway", "toMonth": 11, "fromMonth": 8}, {"_key": "phase005", "label": "Annual General Meeting & season wrap", "toMonth": 12, "fromMonth": 12}], "srSummary": "Competitive tryouts run January, February or May depending on age group. Recreational registration runs April 1 to June 15. Rec practices start mid-July and games run mid-August through the fall. The Annual General Meeting is in December."}, "explore": {"tiles": [{"_key": "1a6b1757", "href": "/referees", "text": "Join a well-trained crew and keep the game fair.", "image": {"alt": "A teenage assistant referee holding a checkered flag on the touchline", "mediaId": "med_referee"}, "title": "Referee", "kicker": "Ages 13+"}, {"_key": "a0f9fdd6", "href": "/competitive#coaches-wanted", "text": "Pick your roster, get training and new gear.", "image": {"alt": "A volunteer coach explaining a drill to players kneeling on the grass", "mediaId": "med_coach"}, "title": "Coach", "kicker": "Coaches wanted"}, {"_key": "0d664a35", "href": "/board", "text": "Meet the volunteers who run the club.", "image": {"alt": "Club volunteers gathered at the edge of a field at dusk", "mediaId": "med_board"}, "title": "Board", "kicker": "2026 board"}, {"_key": "d7d3f79b", "href": "/sponsors", "text": "Put your business on the field.", "image": {"alt": "Volunteers handing out oranges and water under a blue canopy beside the field", "mediaId": "med_sponsors"}, "title": "Sponsor", "kicker": "From $400"}], "title": "There’s a role for everyone", "eyebrow": "Get involved"}, "programs": [{"cta": {"href": "/recreational", "label": "Explore rec", "external": false}, "_key": "2bc2a05e", "text": "Fun-first, local soccer with volunteer coaches. Teams practice once or twice a week and play their games on Saturdays.", "badge": "Practices from mid-July", "facts": [{"_key": "4e14324b", "note": "1–2× a week, set by your coach", "label": "Practices", "value": "Mid-July"}, {"_key": "3c2c3ac0", "note": "Saturdays from mid-August", "label": "Games", "value": "8–10 games"}, {"_key": "5a4eb257", "note": "Apr 1 – Jun 15 (waitlist after)", "label": "Registration", "value": "$170–$185"}, {"_key": "c5df5c13", "note": "Capelli uniform required", "label": "Uniform", "value": "$55 kit"}], "image": {"alt": "Young players dribbling between orange cones while a volunteer coach cheers them on", "mediaId": "med_rec"}, "title": "Rec soccer", "kicker": "Recreational · U6–U19", "secondaryLink": {"href": "/recreational#costs", "label": "See all fees", "external": false}}, {"cta": {"href": "/competitive", "label": "Explore comp", "external": false}, "_key": "eb900d6d", "text": "For players ready for more: tryout-selected teams, longer training, league and cup games across the Sacramento region, and 4+ tournaments a year.", "badge": "Tryouts required", "facts": [{"_key": "4e14324b", "note": "Depending on age group", "label": "Tryouts", "value": "Jan · Feb · May"}, {"_key": "3c2c3ac0", "note": "2-hour sessions", "label": "Training", "value": "2–3× a week"}, {"_key": "5a4eb257", "note": "5 home · 5 away, late Aug – mid Nov", "label": "Fall league", "value": "10 games"}, {"_key": "c5df5c13", "note": "Plus team fee & uniform", "label": "Registration", "value": "$330"}], "image": {"alt": "A teenage player driving forward with the ball as a defender closes in", "mediaId": "med_comp"}, "title": "Comp soccer", "kicker": "Competitive · U9–U19", "secondaryLink": {"href": "/competitive#teams", "label": "Meet the 2026–27 teams", "external": false}}], "eventsSection": {"lead": "Fundraisers, all-star games and club meetings. Tap any event to drop it straight into your calendar.", "title": "Upcoming events", "eyebrow": "Mark your calendar", "newsLink": {"href": "https://www.facebook.com/Prospector-Soccer-Club-108383495868117", "label": "Latest news on Facebook", "external": true}}, "resultsSection": {"lead": "Three PSC teams reached the podium this year. Congratulations, players and coaches!", "link": {"href": "/competitive", "label": "Competitive program", "external": false}, "title": "2026 CUFA Tournament", "eyebrow": "Bragging rights", "resultIds": ["res_1", "res_2", "res_3"]}, "calloutsSection": {"title": "Important right now"}, "programsSection": {"lead": "From first touches to tournament play — compare PSC’s recreational and competitive programs.", "title": "Two ways to play", "eyebrow": "Find your season"}, "sponsorsSection": {"lead": "Thank you to the local businesses that support Prospector Soccer Club.", "link": {"href": "/sponsors", "label": "Become a sponsor", "external": false}, "title": "Our sponsors", "eyebrow": "Thank you"}}, "docId": "home", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "home", "docVersion": 1}
rev_01k70cparn_vojqde	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cparn_vojqde", "data": {"fees": {"lead": "On-time registration runs April 1 – June 15.", "note": "Uniform kit: $55. Capelli uniforms are required.", "title": "Recreational registration", "eyebrow": "Plan your season", "windows": [{"_key": "7d4c9806", "ages": "U6–U12", "price": {"amount": 170}, "grades": "PreKinder–6th grade", "window": "April 1 – June 15", "featured": true, "lateLabel": "After June 15 (waitlist):", "latePrice": {"amount": 185}}, {"_key": "1fc84fba", "ages": "U14–U19", "price": {"amount": 185}, "grades": "7th–12th grade", "window": "April 1 – June 15", "featured": false, "lateLabel": "After June 15 (waitlist):", "latePrice": {"amount": 195}}]}, "hero": {"lead": "Room to learn the game, play as a team and enjoy soccer from U6 through U19.", "chips": [{"_key": "83d2e41d", "text": "U6–U19"}, {"_key": "662b9399", "text": "Practices from mid-July"}, {"_key": "6bc606b2", "text": "8–10 games"}], "image": {"alt": "Young soccer players practicing together on a grass field", "mediaId": "med_rec"}, "title": "Recreational soccer", "eyebrow": "First kicks. Lasting friendships."}, "meta": {"title": "Recreational soccer · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_rec"}, "description": "Recreational youth soccer, U6–U19: season dates, registration fees, equipment and coaching resources at Prospector Soccer Club."}, "glance": {"note": "Practice timing and duration are set by your coach. Fees vary by age and registration date.", "facts": [{"_key": "abda8b79", "label": "Ages", "value": "U6–U19"}, {"_key": "7221616e", "label": "Practices", "value": "1–2 per week"}, {"_key": "305d6abc", "label": "Games", "value": "8–10 · Saturdays"}, {"_key": "06d68aad", "label": "Fees", "value": "From $170"}, {"_key": "1a58e4e9", "label": "Uniform", "value": "$55 · Capelli"}], "title": "At a glance", "buttons": [{"_key": "4b81f18a", "href": "#register", "label": "Registration info", "external": false}, {"_key": "925e6560", "href": "mailto:registrar@prospector.org", "label": "Email the Registrar", "external": false}]}, "season": {"cards": [{"_key": "e78d6308", "icon": "calendar", "text": "Typically begin mid-July, once or twice a week. Your coach sets the schedule and practice duration.", "title": "Practices"}, {"_key": "d3197fb2", "icon": "ball", "text": "8–10 games, typically starting mid-August. Games are usually once a week on Saturdays; game length depends on age level.", "title": "Games"}], "title": "Your season at a glance", "eyebrow": "From practice to game day"}, "subnav": [{"_key": "bf01f54e", "label": "Overview", "anchor": "#overview"}, {"_key": "366e27bd", "label": "Season", "anchor": "#season"}, {"_key": "56729312", "label": "Costs", "anchor": "#costs"}, {"_key": "b5559865", "label": "Register", "anchor": "#register"}, {"_key": "917119e4", "label": "Equipment", "anchor": "#equipment"}, {"_key": "7f4e8674", "label": "Coaching resources", "anchor": "#coaching"}, {"_key": "0d7ab14b", "label": "Policies & FAQ", "anchor": "#policies"}], "coaching": {"lead": "Session plans and age-specific modified rules, ready to open as PDFs.", "title": "A plan for every practice", "eyebrow": "Coaching resources", "documentIds": ["doc_13", "doc_14", "doc_15", "doc_16", "doc_17", "doc_18", "doc_19"]}, "overview": {"body": "Prospector Soccer Club is a non-profit, 100% volunteer-run youth soccer club serving Cameron Park, Shingle Springs and Rescue in the El Dorado County foothills.", "lead": "Recreational soccer for players from U6 to U19.", "title": "A season to grow", "eyebrow": "Play with PSC"}, "policies": {"lead": "Codes of conduct and answers for families.", "title": "Our shared sideline standards", "eyebrow": "Policies & FAQ", "documentIds": ["doc_21", "doc_22", "doc_23", "doc_6", "doc_24"]}, "register": {"note": "**Registration runs April 1 – June 15.** Registration after June 15 is by waitlist. Contact the Registrar or Rec Director for registration information.", "title": "Get ready to register", "buttons": [{"_key": "1478c5bd", "href": "mailto:registrar@prospector.org", "label": "Email the Registrar", "external": false}, {"_key": "8f31b330", "href": "mailto:recdirector@prospector.org", "label": "Email the Rec Director", "external": false}], "eyebrow": "April 1 – June 15"}, "actionBar": {"buttons": [{"_key": "4b8e5357", "href": "#register", "label": "Register info", "external": false}, {"_key": "53705c95", "href": "mailto:recdirector@prospector.org", "label": "Email us", "external": false}]}, "equipment": {"image": {"alt": "Soccer cleats, shin guards and a ball ready for practice", "mediaId": "med_equipment"}, "items": [{"_key": "b6406667", "icon": "users", "text": "$55 · Capelli uniforms required", "title": "Uniform kit"}, {"_key": "5e7b5bf5", "icon": "check", "text": "For practices and games", "title": "Shin guards"}, {"_key": "f8f156b3", "icon": "check", "text": "Bring your cleats", "title": "Soccer cleats"}, {"_key": "18138017", "icon": "check", "text": "Bring water to the field", "title": "Water bottle"}, {"_key": "d9f6e991", "icon": "ball", "text": "Choose the size for your age group", "title": "Practice ball"}], "title": "Ready for the field", "eyebrow": "Equipment", "ballSizes": [{"_key": "b26ea3e8", "ages": "U6–U8", "size": 3}, {"_key": "ebac1532", "ages": "U10–U12", "size": 4}, {"_key": "20a7984a", "ages": "U14–U19", "size": 5}]}}, "docId": "recreational", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "recreational", "docVersion": 1}
rev_01k70cpbbd_3e69g3	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cpbbd_3e69g3", "data": {"hero": {"lead": "Longer training, tournament play and room to grow for players ready for the next challenge.", "chips": [{"_key": "24ba22a2", "text": "U9–U19 · Girls & boys"}, {"_key": "c8e2fc1f", "text": "Fall 2026 / Spring 2027"}, {"_key": "e929ae86", "text": "Volunteer head coaches"}], "image": {"alt": "Competitive youth soccer players contesting the ball on the field", "mediaId": "med_comp"}, "title": "Competitive soccer", "eyebrow": "Take your game further"}, "meta": {"title": "Competitive soccer · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_comp"}, "description": "Explore PSC competitive soccer: 2026–27 teams, tournament results, annual costs, coach opportunities and FAQs."}, "costs": {"items": [{"_key": "ad945f4d", "note": "For the fall season, once accepted onto a comp team.", "color": "c1", "label": "Registration", "price": {"amount": 330}}, {"_key": "d6431052", "note": "Covers at least two tournaments per year.", "color": "c2", "label": "Suggested team fee", "price": {"amount": 200}}, {"_key": "d0838599", "note": "A separate fee for the optional spring season.", "color": "c3", "label": "Spring", "price": {"max": 150, "amount": 100}}, {"_key": "86a66f0b", "note": "Usually last 2–3 years.", "color": "c4", "label": "Uniforms", "price": {"max": 200, "amount": 160}}], "title": "Plan for the year", "total": {"note": "Estimated total including a uniform purchase", "label": "About $790–$880 for a full year"}, "eyebrow": "Competitive costs", "documentIds": ["doc_25"], "estimateNote": "Estimate: $330 + $200 + $100–$150 + $160–$200. Actual costs depend on spring participation and whether a new uniform is needed."}, "subnav": [{"_key": "88c89c1b", "label": "Overview", "anchor": "#overview"}, {"_key": "7d05f532", "label": "Results", "anchor": "#results"}, {"_key": "9841529d", "label": "Teams", "anchor": "#teams"}, {"_key": "d1d3f93b", "label": "Costs", "anchor": "#costs"}, {"_key": "2c517bc4", "label": "Coaches wanted", "anchor": "#coaches-wanted"}, {"_key": "a9dcb455", "label": "FAQ", "anchor": "#faq"}], "coaches": {"image": {"alt": "A volunteer coach explaining a drill to players on the grass", "mediaId": "med_coach"}, "title": "Help players reach further", "eyebrow": "Coach with PSC", "benefits": [{"_key": "5875aa3b", "text": "Choose your own roster."}, {"_key": "a7894b60", "text": "Better practice fields, usually granted based on availability."}, {"_key": "8fc4ba4a", "text": "Give back through player enrichment."}], "newItems": [{"_key": "0efc82d4", "text": "Partnership with The Coaching Manual for coach education and training."}, {"_key": "964052c7", "text": "VEO cameras to record some home games."}, {"_key": "fca3232a", "text": "Competition soccer balls."}, {"_key": "673ecb74", "text": "Goalie training."}], "newTitle": "New this year", "applyCard": {"body": "Submit a filled-out application. A Grassroots course for your age group is suggested. Coaches are encouraged to take U.S. Soccer Learning Center courses: the introduction course is free; Grassroots courses are 2 hours and $25, reimbursed by the club once the certificate is received.", "title": "Apply and keep learning", "buttons": [{"_key": "0be832ca", "href": "https://prospector.org/wp-content/uploads/sites/206/2026/01/2026-Comp-Coach-Application.pdf", "label": "2026 Comp Coach Application PDF", "external": true}, {"_key": "11e5eeb4", "href": "https://learning.ussoccer.com/coach", "label": "U.S. Soccer Learning Center", "external": true}]}, "benefitsTitle": "Competitive coaches wanted"}, "overview": {"cards": [{"_key": "4608b324", "icon": "calendar", "text": "Typically April through December, with spring and post-league cup options. Two or three 2-hour practices each week.", "title": "The playing year"}, {"_key": "bd5af268", "icon": "ball", "text": "10 games: 5 home and 5 away, from late August to mid-November. Teams play cup games in addition to fall league.", "title": "Fall league"}, {"_key": "61340c74", "icon": "users", "text": "Boys and girls, U9 through U19. 7v7 at U9, 9v9 at U11, and 11v11 at U13 and older.", "title": "Age groups"}, {"_key": "7c2ead47", "icon": "waving-flag", "text": "Volunteer head coaches are appointed through an application. Some teams add professional coaches or trainers.", "title": "Coaching"}], "title": "More time on the ball", "columns": [{"_key": "c9b61e94", "title": "Finding your team", "bullets": [{"_key": "8a1ae1e4", "text": "Team selection is by tryouts in January, February or May, depending on age group. Players must attend tryouts."}, {"_key": "2d60f71b", "text": "A second team may form depending on tryout numbers and coach availability."}, {"_key": "25a09607", "text": "Teams train longer and usually play 4+ tournaments a year."}]}, {"_key": "22b93141", "title": "Beyond the home field", "bullets": [{"_key": "8a1ae1e4", "text": "Teams typically enter 4–5 tournaments, including at least one overnight travel tournament, such as the Bay Area or Santa Cruz."}, {"_key": "2d60f71b", "text": "Non-CYSA options include sand soccer and small-sided games."}, {"_key": "25a09607", "text": "League games are mostly in the Sacramento region, extending north to Chico and south to Modesto."}]}], "eyebrow": "The competitive program"}, "actionBar": {"buttons": [{"_key": "ca7766c8", "href": "#teams", "label": "Meet the teams", "external": false}, {"_key": "c516a5a3", "href": "mailto:compdirector@prospector.org", "label": "Email us", "external": false}]}, "faqSection": {"title": "Competitive questions", "eyebrow": "Good to know"}, "teamsSection": {"lead": "11 teams, with girls and boys competing across four levels.", "title": "Meet the teams", "seasonLabel": "Fall 2026 / Spring 2027"}, "resultsSection": {"title": "2026 CUFA Tournament", "eyebrow": "On the podium", "resultIds": ["res_1", "res_2", "res_3"]}}, "docId": "competitive", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "competitive", "docVersion": 1}
rev_01k70cpbqn_gm3m3s	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cpbqn_gm3m3s", "data": {"cta": {"text": "Contact Matthew Hamedian to learn about joining the referee program.", "title": "Ready to step onto the field?", "buttons": [{"_key": "097bc589", "href": "mailto:refereedirector@prospector.org", "label": "Become a referee", "external": false}], "eyebrow": "Your next step"}, "why": {"cards": [{"_key": "0d01a223", "icon": "check", "text": "Help provide a safe, enjoyable environment for players of all ages and skill levels.", "title": "A safe game"}, {"_key": "24e48485", "icon": "book", "text": "Learn and correctly apply the Laws of the Game.", "title": "Know the laws"}, {"_key": "e36f0bbe", "icon": "waving-flag", "text": "Join a program that recruits, develops and advances referees at all levels.", "title": "Keep developing"}, {"_key": "56dc138b", "icon": "users", "text": "Referees are needed, age 13 and up.", "title": "Start at 13+"}], "title": "Why referee", "eyebrow": "Be part of the game"}, "hero": {"lead": "Help provide a safe, enjoyable soccer environment for players of every age and skill level.", "chips": [{"_key": "26bb4fab", "text": "Referees needed"}, {"_key": "45aa4c0f", "text": "Age 13 and up"}, {"_key": "e9cc103a", "text": "Develop at every level"}], "image": {"alt": "An assistant referee holding a checkered flag beside the soccer field", "mediaId": "med_referee"}, "title": "Referees", "eyebrow": "Know the game. Guide the game."}, "meta": {"title": "Referees · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_referee"}, "description": "Join the PSC referee program, age 13 and up. Contact Referee Director Matthew Hamedian and find the Laws of the Game."}, "contact": {"title": "Connect with our referee director", "eyebrow": "Get involved", "buttonLabel": "Email Matthew", "documentIds": ["doc_4"], "boardMemberId": "mem_7"}, "program": {"body": "Referees are critical to Prospector Soccer Club’s success. Our program builds a qualified, well-trained group of referees held to high standards. We actively recruit, develop and advance referees at all levels.\\n\\nReferees should know and correctly apply the Laws of the Game.", "title": "An essential part of the game", "eyebrow": "The referee program"}}, "docId": "referees", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "referees", "docVersion": 1}
