rev_01k70cql8s_f0bti4	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cql8s_f0bti4", "data": {"kind": "pdf", "title": "PSC Comp Sponsorship Information", "source": {"url": "https://www.prospector.org/wp-content/uploads/sites/206/2023/08/PSC-Comp-Sponsorship-Information.pdf", "mode": "url"}, "category": "club", "external": true, "description": "Sponsorship information for the competitive program.", "showInLibrary": false}, "docId": "doc_25", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "documents", "docVersion": 1}
rev_01k70cqlnh_lrhbt8	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cqlnh_lrhbt8", "data": {"page": "competitive", "answer": "Only depending on the coach. At minimum, there is a fall season and two tournaments. Some coaches play indoor/futsal in winter; spring is optional.", "question": "Is comp year-round?"}, "docId": "faq_1", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1}
rev_01k70cqm6n_9skd03	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cqm6n_9skd03", "data": {"page": "competitive", "answer": "Mostly locally: Sacramento, Folsom and El Dorado Hills, with some games in Roseville, Yuba City, Chico and Truckee. Not every division has teams in the farther locations. League play can extend south to Modesto; teams typically also enter at least one overnight travel tournament.", "question": "How far do we travel?"}, "docId": "faq_2", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1}
rev_01k70cqmn0_e478ht	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cqmn0_e478ht", "data": {"page": "competitive", "answer": "Players must attend tryouts, held in January, February or May depending on age group. A second team may form depending on tryout numbers and coach availability.", "question": "How do tryouts work?"}, "docId": "faq_3", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1}
rev_01k70cqn6j_sokia5	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cqn6j_sokia5", "data": {"page": "competitive", "answer": "Playing formats are 7v7 at U9, 9v9 at U11, and 11v11 at U13 and older.", "question": "What is the team size by age?"}, "docId": "faq_4", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1}
rev_01k70cqnm4_4gkv2a	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cqnm4_4gkv2a", "data": {"page": "competitive", "answer": "The U.S. Soccer Learning Center introduction course is free. Grassroots courses are 2 hours and $25; the club reimburses the course fee once the certificate is received.", "question": "Is coach education reimbursed?"}, "docId": "faq_5", "action": "created", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1}
