rev_01k70cr0gp_ggb57e	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_ggb57e", "data": {"cta": {"text": "Not sure which program fits, or need help with registration? Our communications director will point you in the right direction.", "title": "We’re here to help", "buttons": [{"_key": "15f6dc59", "href": "mailto:communicationsdirector@prospector.org", "label": "Email the club", "external": false}, {"_key": "26e52855", "href": "/resources", "label": "Resources", "external": false}], "eyebrow": "Questions?"}, "band": {"lead": "PSC is a non-profit, volunteer-run club — from the board members who run it to the volunteer head coaches on the sideline.", "image": {"alt": "", "mediaId": "med_about"}, "stats": [{"_key": "968c17a8", "label": "volunteer-run, non-profit club", "value": "100%"}, {"_key": "d4671c45", "label": "every age, from first kicks to seniors", "value": "U6–U19"}, {"_key": "e866d3ca", "label": "competitive teams for Fall 2026 / Spring 2027", "value": "11"}, {"_key": "b4b32821", "label": "communities: Cameron Park, Shingle Springs & Rescue", "value": "3"}], "title": "Run by volunteers.\\nPowered by Gold Country.", "eyebrow": "Built by neighbors"}, "hero": {"lead": "A non-profit, volunteer-run club where kids from U6 to U19 learn the game, grow as teammates, and fall in love with Saturday mornings in the foothills.", "image": {"alt": "Youth soccer players racing for the ball at golden hour on a foothill field ringed by oak trees", "mediaId": "med_hero"}, "pills": [{"_key": "00fd783b", "text": "Non-profit · 100% volunteer-run"}, {"_key": "6116b6e0", "text": "Ages U6–U19"}, {"_key": "13355024", "text": "Rec & Comp"}], "title": "Gold Country’s home for *youth soccer*", "eyebrow": "Cameron Park · Shingle Springs · Rescue", "primaryCta": {"href": "/recreational", "label": "Recreational program", "external": false}, "secondaryCta": {"href": "/competitive", "label": "Competitive teams", "external": false}}, "meta": {"title": "Prospector Soccer Club", "ogIm