": "Join a well-trained crew and keep the game fair.", "image": {"alt": "A teenage assistant referee holding a checkered flag on the touchline", "mediaId": "med_referee"}, "title": "Referee", "kicker": "Ages 13+"}, {"_key": "a0f9fdd6", "href": "/competitive#coaches-wanted", "text": "Pick your roster, get training and new gear.", "image": {"alt": "A volunteer coach explaining a drill to players kneeling on the grass", "mediaId": "med_coach"}, "title": "Coach", "kicker": "Coaches wanted"}, {"_key": "0d664a35", "href": "/board", "text": "Meet the volunteers who run the club.", "image": {"alt": "Club volunteers gathered at the edge of a field at dusk", "mediaId": "med_board"}, "title": "Board", "kicker": "2026 board"}, {"_key": "d7d3f79b", "href": "/sponsors", "text": "Put your business on the field.", "image": {"alt": "Volunteers handing out oranges and water under a blue canopy beside the field", "mediaId": "med_sponsors"}, "title": "Sponsor", "kicker": "From $400"}], "title": "There’s a role for everyone", "eyebrow": "Get involved"}, "programs": [{"cta": {"href": "/recreational", "label": "Explore rec", "external": false}, "_key": "2bc2a05e", "text": "Fun-first, local soccer with volunteer coaches. Teams practice once or twice a week and play their games on Saturdays.", "badge": "Practices from mid-July", "facts": [{"_key": "4e14324b", "note": "1–2× a week, set by your coach", "label": "Practices", "value": "Mid-July"}, {"_key": "3c2c3ac0", "note": "Saturdays from mid-August", "label": "Games", "value": "8–10 games"}, {"_key": "5a4eb257", "note": "Apr 1 – Jun 15 (waitlist after)", "label": "Registration", "value": "$170–$185"}, {"_key": "c5df5c13", "note": "Capelli uniform required", "label": "Uniform", "value": "$55 kit"}], "image": {"alt": "Young players dribbling between orange cones while a volunteer coach cheers them on", "mediaId": "med_rec"}, "title": "Rec soccer", "kicker": "Recreational · U6–U19", "secondaryLink": {"href": "/recreational#costs", "label": "See all fees", "external": false}}, {"cta": {"href": "/competitive", "label": "Explore comp", "external": false}, "_key": "eb900d6d", "text": "For players ready for more: tryout-selected teams, longer training, league and cup games across the Sacramento region, and 4+ tournaments a year.", "badge": "Tryouts required", "facts": [{"_key": "4e14324b", "note": "Depending on age group", "label": "Tryouts", "value": "Jan · Feb · May"}, {"_key": "3c2c3ac0", "note": "2-hour sessions", "label": "Training", "value": "2–3× a week"}, {"_key": "5a4eb257", "note": "5 home · 5 away, late Aug – mid Nov", "label": "Fall league", "value": "10 games"}, {"_key": "c5df5c13", "note": "Plus team fee & uniform", "label": "Registration", "value": "$330"}], "image": {"alt": "A teenage player driving forward with the ball as a defender closes in", "mediaId": "med_comp"}, "title": "Comp soccer", "kicker": "Competitive · U9–U19", "secondaryLink": {"href": "/competitive#teams", "label": "Meet the 2026–27 teams", "external": false}}], "eventsSection": {"lead": "Fundraisers, all-star games and club meetings. Tap any event to drop it straight into your calendar.", "title": "Upcoming events", "eyebrow": "Mark your calendar", "newsLink": {"href": "https://www.facebook.com/Prospector-Soccer-Club-108383495868117", "label": "Latest news on Facebook", "external": true}}, "resultsSection": {"lead": "Three PSC teams reached the podium this year. Congratulations, players and coaches!", "link": {"href": "/competitive", "label": "Competitive program", "external": false}, "title": "2026 CUFA Tournament", "eyebrow": "Bragging rights", "resultIds": ["res_1", "res_2", "res_3"]}, "calloutsSection": {"title": "Important right now"}, "programsSection": {"lead": "From first touches to tournament play — compare PSC’s recreational and competitive programs.", "title": "Two ways to play", "eyebrow": "Find your season"}, "sponsorsSection": {"lead": "Thank you to the local businesses that support Prospector Soccer Club.", "link": {"href": "/sponsors", "label": "Become a sponsor", "external": false}, "title": "Our sponsors", "eyebrow": "Thank you"}}, "docId": "home", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "home", "docVersion": 1, "publishSiteVersion": 1}
