rev_01k70cr0gp_7jpu2u	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_7jpu2u", "data": {"hero": {"lead": "Longer training, tournament play and room to grow for players ready for the next challenge.", "chips": [{"_key": "24ba22a2", "text": "U9–U19 · Girls & boys"}, {"_key": "c8e2fc1f", "text": "Fall 2026 / Spring 2027"}, {"_key": "e929ae86", "text": "Volunteer head coaches"}], "image": {"alt": "Competitive youth soccer players contesting the ball on the field", "mediaId": "med_comp"}, "title": "Competitive soccer", "eyebrow": "Take your game further"}, "meta": {"title": "Competitive soccer · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_comp"}, "description": "Explore PSC competitive soccer: 2026–27 teams, tournament results, annual costs, coach opportunities and FAQs."}, "costs": {"items": [{"_key": "ad945f4d", "note": "For the fall season, once accepted onto a comp team.", "color": "c1", "label": "Registration", "price": {"amount": 330}}, {"_key": "d6431052", "note": "Covers at least two tournaments per year.", "color": "c2", "label": "Suggested team fee", "price": {"amount": 200}}, {"_key": "d0838599", "note": "A separate fee for the optional spring season.", "color": "c3", "label": "Spring", "price": {"max": 150, "amount": 100}}, {"_key": "86a66f0b", "note": "Usually last 2–3 years.", "color": "c4", "label": "Uniforms", "price": {"max": 200, "amount": 160}}], "title": "Plan for the year", "total": {"note": "Estimated total including a uniform purchase", "label": "About $790–$880 for a full year"}, "eyebrow": "Competitive costs", "documentIds": ["doc_25"], "estimateNote": "Estimate: $330 + $200 + $100–$150 + $160–$200. Actual costs depend on spring participation and whether a new uniform is needed."}, "subnav": [{"_key": "88c89c1b", "label": "Overview", "anchor": "#overview"}, {"_key": "7d05f532", "label": "Results", "anchor": "#results"}, {"_key": "9841529d", "label": "Teams", "anchor": "#teams"}, {"_key": "d1d3f93b", "label": "Costs", "anchor": "#costs"}, {"_key": "2c517bc4", "label": "Coaches wanted", "anchor": "#coaches-wanted"}, {"_key": "a9dcb455", "label": "FAQ", "anchor": "#faq"}], "coaches": {"image": {"alt": "A volunteer coach explaining a drill to players on the grass", "mediaId": "med_coach"}, "title": "Help players reach further", "eyebrow": "Coach with PSC", "benefits": [{"_key": "5875aa3b", "text": "Choose your own roster."}, {"_key": "a7894b60", "text": "Better practice fields, usually granted based on availability."}, {"_key": "8fc4ba4a", "text": "Give back through player enrichment."}], "newItems": [{"_key": "0efc82d4", "text": "Partnership with The Coaching Manual for coach education and training."}, {"_key": "964052c7", "text": "VEO cameras to record some home games."}, {"_key": "fca3232a", "text": "Competition soccer balls."}, {"_key": "673ecb74", "text": "Goalie training."}], "newTitle": "New this year", "applyCard": {"body": "Submit a filled-out application. A Grassroots course for your age group is suggested. Coaches are encouraged to take U.S. Soccer Learning Center courses: the introduction course is free; Grassroots courses are 2 hours and $25, reimbursed by the club once the certificate is received.", "title": "Apply and keep learning", "buttons": [{"_key": "0be832ca", "href": "https://prospector.org/wp-content/uploads/sites/206/2026/01/2026-Comp-Coach-Application.pdf", "label": "2026 Comp Coach Application PDF", "external": true}, {"_key": "11e5eeb4", "href": "https://learning.ussoccer.com/coach", "label": "U.S. Soccer Learning Center", "external": true}]}, "benefitsTitle": "Competitive coaches wanted"}, "overview": {"cards": [{"_key": "4608b324", "icon": "calendar", "text": "Typically April through December, with spring and post-league cup options. Two or three 2-hour practices each week.", "title": "The playing year"}, {"_key": "bd5af268", "icon": "ball", "text": "10 games: 5 home and 5 away, from late August to mid-November. Teams play cup games in addition to fall league.", "title": "Fall league"}, {"_key": "61340c74", "icon": "users", "text": "Boys and girls, U9 through U19. 7v7 at U9, 9v9 at U11, and 11v11 at U13 and older.", "title": "Age groups"}, {"_key": "7c2ead47", "icon": "waving-flag", "text": "Volunteer head coaches are appointed through an application. Some teams add professional coaches or trainers.", "title": "Coaching"}], "title": "More time on the ball", "columns": [{"_key": "c9b61e94", "title": "Finding your team", "bullets": [{"_key": "8a1ae1e4", "text": "Team selection is by tryouts in January, February or May, depending on age group. Players must attend tryouts."}, {"_key": "2d60f71b", "text": "A second team may form depending on tryout numbers and coach availability."}, {"_key": "25a09607", "text": "Teams train longer and usually play 4+ tournaments a year."}]}, {"_key": "22b93141", "title": "Beyond the home field", "bullets": [{"_key": "8a1ae1e4", "text": "Teams typically enter 4–5 tournaments, including at least one overnight travel tournament, such as the Bay Area or Santa Cruz."}, {"_key": "2d60f71b", "text": "Non-CYSA options include sand soccer and small-sided games."}, {"_key": "25a09607", "text": "League games are mostly in the Sacramento region, extending north to Chico and south to Modesto."}]}], "eyebrow": "The competitive program"}, "actionBar": {"buttons": [{"_key": "ca7766c8", "href": "#teams", "label": "Meet the teams", "external": false}, {"_key": "c516a5a3", "href": "mailto:compdirector@prospector.org", "label": "Email us", "external": false}]}, "faqSection": {"title": "Competitive questions", "eyebrow": "Good to know"}, "teamsSection": {"lead": "11 teams, with girls and boys competing across four levels.", "title": "Meet the teams", "seasonLabel": "Fall 2026 / Spring 2027"}, "resultsSection": {"title": "2026 CUFA Tournament", "eyebrow": "On the podium", "resultIds": ["res_1", "res_2", "res_3"]}}, "docId": "competitive", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "competitive", "docVersion": 1, "publishSiteVersion": 1}
rev_01k70cr0gp_7mt6jv	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_7mt6jv", "data": {"cta": {"text": "Contact Matthew Hamedian to learn about joining the referee program.", "title": "Ready to step onto the field?", "buttons": [{"_key": "097bc589", "href": "mailto:refereedirector@prospector.org", "label": "Become a referee", "external": false}], "eyebrow": "Your next step"}, "why": {"cards": [{"_key": "0d01a223", "icon": "check", "text": "Help provide a safe, enjoyable environment for players of all ages and skill levels.", "title": "A safe game"}, {"_key": "24e48485", "icon": "book", "text": "Learn and correctly apply the Laws of the Game.", "title": "Know the laws"}, {"_key": "e36f0bbe", "icon": "waving-flag", "text": "Join a program that recruits, develops and advances referees at all levels.", "title": "Keep developing"}, {"_key": "56dc138b", "icon": "users", "text": "Referees are needed, age 13 and up.", "title": "Start at 13+"}], "title": "Why referee", "eyebrow": "Be part of the game"}, "hero": {"lead": "Help provide a safe, enjoyable soccer environment for players of every age and skill level.", "chips": [{"_key": "26bb4fab", "text": "Referees needed"}, {"_key": "45aa4c0f", "text": "Age 13 and up"}, {"_key": "e9cc103a", "text": "Develop at every level"}], "image": {"alt": "An assistant referee holding a checkered flag beside the soccer field", "mediaId": "med_referee"}, "title": "Referees", "eyebrow": "Know the game. Guide the game."}, "meta": {"title": "Referees · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_referee"}, "description": "Join the PSC referee program, age 13 and up. Contact Referee Director Matthew Hamedian and find the Laws of the Game."}, "contact": {"title": "Connect with our referee director", "eyebrow": "Get involved", "buttonLabel": "Email Matthew", "documentIds": ["doc_4"], "boardMemberId": "mem_7"}, "program": {"body": "Referees are critical to Prospector Soccer Club’s success. Our program builds a qualified, well-trained group of referees held to high standards. We actively recruit, develop and advance referees at all levels.\\n\\nReferees should know and correctly apply the Laws of the Game.", "title": "An essential part of the game", "eyebrow": "The referee program"}}, "docId": "referees", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "referees", "docVersion": 1, "publishSiteVersion": 1}
