rev_01k70cr0gp_bbo6s3	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_bbo6s3", "data": {"hero": {"lead": "Find club documents, safety information, coaching plans and the forms you need.", "chips": [{"_key": "c4981fd2", "text": "Club documents"}, {"_key": "b2fd1ddd", "text": "Coaching plans"}, {"_key": "11dfcb28", "text": "Safety & health"}], "image": {"alt": "Soccer coaching materials and equipment ready for a session", "mediaId": "med_resources"}, "title": "Resources & forms", "eyebrow": "The club library"}, "meta": {"title": "Resources & forms · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_resources"}, "description": "PSC document library: governance, codes of conduct, safety fact sheets, coaching session plans, modified rules and the Cal North injury claim form."}, "library": {"lead": "Search by title or choose a category. PDFs and the online form open in a new tab.", "title": "Find what you need", "eyebrow": "Document library", "emptyText": "No documents match your search. Try another term or choose All.", "categories": [{"key": "all", "_key": "f9777506", "label": "All"}, {"key": "club", "_key": "264c38dd", "label": "Club documents"}, {"key": "safety", "_key": "88f19624", "label": "Safety & health"}, {"key": "coaching", "_key": "17e29e18", "label": "Coaching"}, {"key": "forms", "_key": "bf369658", "label": "Forms"}], "searchPlaceholder": "Search documents"}, "formsNote": "**Submit within 90 days of the incident.** Online submissions only; hard-copy submissions are no longer accepted. This is secondary insurance with a $500 deductible."}, "docId": "resources", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "resources", "docVersion": 1, "publishSiteVersion": 1}
rev_01k70cr0gp_gci840	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_gci840", "data": {"cta": {"text": "Explore recreational and competitive soccer with Prospector Soccer Club.", "title": "Find your place on the field", "buttons": [{"_key": "14fe972d", "href": "/recreational", "label": "Recreational soccer", "external": false}, {"_key": "9ece96ca", "href": "/competitive", "label": "Competitive soccer", "external": false}], "eyebrow": "Your next step"}, "hero": {"lead": "A community soccer club with room for every player to grow.", "chips": [{"_key": "e4534c9e", "text": "Non-profit"}, {"_key": "b06bd51d", "text": "100% volunteer-run"}, {"_key": "d41ab1fd", "text": "Cameron Park · Shingle Springs · Rescue"}], "image": {"alt": "A soccer field in the California foothills", "mediaId": "med_about"}, "title": "About Prospector", "eyebrow": "Rooted in the foothills"}, "meta": {"title": "About Prospector · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_about"}, "description": "Learn about Prospector Soccer Club: our communities, purpose, vision, mission and five core values."}, "values": {"items": [{"_key": "0ddc427a", "text": "Building trust and communication. We win and lose together.", "title": "Teamwork"}, {"_key": "db1cd063", "text": "For the game, teammates, opponents, coaches and officials.", "title": "Respect"}, {"_key": "92417ac3", "text": "Following the rules and staying committed.", "title": "Discipline"}, {"_key": "4d5b5d6e", "text": "Fair play, honesty and transparency.", "title": "Integrity"}, {"_key": "60d58276", "text": "Building lasting relationships through soccer.", "title": "Community"}], "title": "The values we play by", "eyebrow": "Our core values"}, "vision": {"body": "Every player, recreational or competitive, should have room to grow and a lasting love of the game.", "lead": "To be a cornerstone of the community: developing players at every level while championing teamwork, respect, discipline, integrity and community.", "image": {"alt": "Sunrise across a soccer pitch in the foothills", "mediaId": "med_pitch_sunrise"}, "title": "Room to grow", "eyebrow": "Looking ahead", "heading": "Our vision"}, "mission": {"image": {"alt": "A soccer field in the California foothills", "mediaId": "med_about"}, "title": "A rewarding place to play", "bullets": [{"_key": "f37ddd00", "text": "Give every player a supportive, rewarding place to play, focused on fun, enjoyment and skill at their level of interest and ability."}, {"_key": "ab421b8b", "text": "Create a challenging environment for players who want to reach their full potential."}, {"_key": "bdfddaab", "text": "Foster physical, mental and emotional growth through soccer at all ages and levels."}], "eyebrow": "What brings us together", "heading": "Our mission"}, "purpose": {"lead": "Prospector Soccer Club (PSC) serves Cameron Park, Shingle Springs and Rescue, California, in the El Dorado County foothills.", "title": "A club for our community", "eyebrow": "Our purpose", "statement": "Our purpose is to lead in developing young talent and to administer and promote an organized, non-profit, volunteer soccer program for the children of our club’s territory."}}, "docId": "about", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "about", "docVersion": 1, "publishSiteVersion": 1}
