rev_01k70cr0gp_vu5nor	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_vu5nor", "data": {"page": "competitive", "answer": "Only depending on the coach. At minimum, there is a fall season and two tournaments. Some coaches play indoor/futsal in winter; spring is optional.", "question": "Is comp year-round?"}, "docId": "faq_1", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1, "publishSiteVersion": 1}
rev_01k70cr0gp_ha11v4	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_ha11v4", "data": {"page": "competitive", "answer": "Mostly locally: Sacramento, Folsom and El Dorado Hills, with some games in Roseville, Yuba City, Chico and Truckee. Not every division has teams in the farther locations. League play can extend south to Modesto; teams typically also enter at least one overnight travel tournament.", "question": "How far do we travel?"}, "docId": "faq_2", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1, "publishSiteVersion": 1}
rev_01k70cr0gp_eo5loo	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_eo5loo", "data": {"page": "competitive", "answer": "Players must attend tryouts, held in January, February or May depending on age group. A second team may form depending on tryout numbers and coach availability.", "question": "How do tryouts work?"}, "docId": "faq_3", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1, "publishSiteVersion": 1}
rev_01k70cr0gp_b2hhki	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_b2hhki", "data": {"page": "competitive", "answer": "Playing formats are 7v7 at U9, 9v9 at U11, and 11v11 at U13 and older.", "question": "What is the team size by age?"}, "docId": "faq_4", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1, "publishSiteVersion": 1}
rev_01k70cr0gp_4b4dbi	{"at": "2026-11-09T14:53:20.127Z", "id": "rev_01k70cr0gp_4b4dbi", "data": {"page": "competitive", "answer": "The U.S. Soccer Learning Center introduction course is free. Grassroots courses are 2 hours and $25; the club reimburses the course fee once the certificate is received.", "question": "Is coach education reimbursed?"}, "docId": "faq_5", "action": "published", "authorId": "seed", "sealedAt": "2026-11-09T14:53:20.127Z", "authorName": "Content migration", "collection": "faqs", "docVersion": 1, "publishSiteVersion": 1}
