published	{"docs": {"faqs": [{"id": "faq_1", "data": {"page": "competitive", "answer": "Only depending on the coach. At minimum, there is a fall season and two tournaments. Some coaches play indoor/futsal in winter; spring is optional.", "question": "Is comp year-round?"}, "order": 0, "version": 1, "collection": "faqs"}, {"id": "faq_2", "data": {"page": "competitive", "answer": "Mostly locally: Sacramento, Folsom and El Dorado Hills, with some games in Roseville, Yuba City, Chico and Truckee. Not every division has teams in the farther locations. League play can extend south to Modesto; teams typically also enter at least one overnight travel tournament.", "question": "How far do we travel?"}, "order": 1, "version": 1, "collection": "faqs"}, {"id": "faq_3", "data": {"page": "competitive", "answer": "Players must attend tryouts, held in January, February or May depending on age group. A second team may form depending on tryout numbers and coach availability.", "question": "How do tryouts work?"}, "order": 2, "version": 1, "collection": "faqs"}, {"id": "faq_4", "data": {"page": "competitive", "answer": "Playing formats are 7v7 at U9, 9v9 at U11, and 11v11 at U13 and older.", "question": "What is the team size by age?"}, "order": 3, "version": 1, "collection": "faqs"}, {"id": "faq_5", "data": {"page": "competitive", "answer": "The U.S. Soccer Learning Center introduction course is free. Grassroots courses are 2 hours and $25; the club reimburses the course fee once the certificate is received.", "question": "Is coach education reimbursed?"}, "order": 4, "version": 1, "collection": "faqs"}, {"id": "faq_shop_0", "data": {"page": "shop", "answer": "This is a proof of concept only. You can explore products and try the cart, but no orders are accepted.", "question": "How do pre-orders work?"}, "order": 5, "version": 2, "collection": "faqs"}, {"id": "faq_shop_1", "data": {"page": "shop", "answer": "No pickup is scheduled. Fulfillment details shown in this concept are illustrative.", "question": "Where can I pick up my order?"}, "order": 6, "version": 2, "collection": "faqs"}, {"id": "faq_shop_2", "data": {"page": "shop", "answer": "No payments are accepted. Checkout is disabled for this proof of concept.", "question": "How do I pay?"}, "order": 7, "version": 2, "collection": "faqs"}, {"id": "faq_shop_3", "data": {"page": "shop", "answer": "No products are being sold through this showcase. Sizes and exchange details are illustrative.", "question": "Can I exchange a size?"}, "order": 8, "version": 2, "collection": "faqs"}], "home": [{"id": "home", "data": {"cta": {"text": "Not sure which program fits, or need help with registration? Our communications director will point you in the right direction.", "title": "We’re here to help", "buttons": [{"_key": "15f6dc59", "href": "mailto:communicationsdirector@prospector.org", "label": "Email the club", "external": false}, {"_key": "26e52855", "href": "/resources", "label": "Resources", "external": false}], "eyebrow": "Questions?"}, "band": {"lead": "PSC is a non-profit, volunteer-run club — from the board members who run it to the volunteer head coaches on the sideline.", "image": {"alt": "", "mediaId": "med_about"}, "stats": [{"_key": "968c17a8", "label": "volunteer-run, non-profit club", "value": "100%"}, {"_key": "d4671c45", "label": "every age, from first kicks to seniors", "value": "U6–U19"}, {"_key": "e866d3ca", "label": "competitive teams for Fall 2026 / Spring 2027", "value": "11"}, {"_key": "b4b32821", "label": "communities: Cameron Park, Shingle Springs & Rescue", "value": "3"}], "title": "Run by volunteers.\\nPowered by Gold Country.", "eyebrow": "Built by neighbors"}, "hero": {"lead": "A non-profit, volunteer-run club where kids from U6 to U19 learn the game, grow as teammates, and fall in love with Saturday mornings in the foothills.", "image": {"alt": "Youth soccer players racing for the ball at golden hour on a foothill field ringed by oak trees", "mediaId": "med_hero"}, "pills": [{"_key": "00fd783b", "text": "Non-profit · 100% volunteer-run"}, {"_key": "6116b6e0", "text": "Ages U6–U19"}, {"_key": "13355024", "text": "Rec & Comp"}], "title": "Gold Country’s home for *youth soccer*", "eyebrow": "Cameron Park · Shingle Springs · Rescue", "primaryCta": {"href": "/recreational", "label": "Recreational program", "external": false}, "secondaryCta": {"href": "/competitive", "label": "Competitive teams", "external": false}}, "meta": {"title": "Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_hero_jpg"}, "description": "Prospector Soccer Club — non-profit, volunteer-run youth soccer for Cameron Park, Shingle Springs and Rescue, California. Recreational U6–U19 and competitive U9–U19."}, "season": {"bands": [{"to": 100, "_key": "0a4a16ea", "from": 25, "kind": "comp"}, {"to": 88, "_key": "1b3db2c6", "from": 54, "kind": "rec"}], "marks": [{"_key": "24ad4c65", "label": "Comp tryouts", "position": 8.33}, {"_key": "e3c4f8e9", "label": "Rec registration", "position": 25}, {"_key": "c38050be", "label": "May tryouts", "position": 37.5}, {"_key": "108a7be4", "label": "Rec practices", "position": 54}, {"_key": "170da577", "label": "Fall games", "position": 64}, {"_key": "45c43bf8", "label": "All-stars", "position": 87.5}], "title": "The PSC year", "legend": [{"_key": "70aaa4f2", "label": "Recreational season (from mid-July)", "swatch": "var(--blue-600)"}, {"_key": "7c17a805", "label": "Competitive season (Apr – Dec)", "swatch": "rgb(11 42 91 / .2)"}, {"_key": "bc24f7bd", "label": "Today", "swatch": "var(--gold-500)"}], "phases": [{"_key": "phase000", "label": "Competitive tryouts (by age group)", "toMonth": 2, "fromMonth": 1}, {"_key": "phase001", "label": "Spring season options for comp teams", "toMonth": 3, "fromMonth": 3}, {"_key": "phase002", "label": "Rec registration is open (Apr 1 – Jun 15)", "toMonth": 6, "fromMonth": 4}, {"_key": "phase003", "label": "Rec practices kick off mid-July", "toMonth": 7, "fromMonth": 7}, {"_key": "phase004", "label": "Fall season is underway", "toMonth": 11, "fromMonth": 8}, {"_key": "phase005", "label": "Annual General Meeting & season wrap", "toMonth": 12, "fromMonth": 12}], "srSummary": "Competitive tryouts run January, February or May depending on age group. Recreational registration runs April 1 to June 15. Rec practices start mid-July and games run mid-August through the fall. The Annual General Meeting is in December."}, "explore": {"tiles": [{"_key": "1a6b1757", "href": "/referees", "text": "Join a well-trained crew and keep the game fair.", "image": {"alt": "A teenage assistant referee holding a checkered flag on the touchline", "mediaId": "med_referee"}, "title": "Referee", "kicker": "Ages 13+"}, {"_key": "a0f9fdd6", "href": "/competitive#coaches-wanted", "text": "Pick your roster, get training and new gear.", "image": {"alt": "A volunteer coach explaining a drill to players kneeling on the grass", "mediaId": "med_coach"}, "title": "Coach", "kicker": "Coaches wanted"}, {"_key": "0d664a35", "href": "/board", "text": "Meet the volunteers who run the club.", "image": {"alt": "Club volunteers gathered at the edge of a field at dusk", "mediaId": "med_board"}, "title": "Board", "kicker": "2026 board"}, {"_key": "d7d3f79b", "href": "/sponsors", "text": "Put your business on the field.", "image": {"alt": "Volunteers handing out oranges and water under a blue canopy beside the field", "mediaId": "med_sponsors"}, "title": "Sponsor", "kicker": "From $400"}], "title": "There’s a role for everyone", "eyebrow": "Get involved"}, "programs": [{"cta": {"href": "/recreational", "label": "Explore rec", "external": false}, "_key": "2bc2a05e", "text": "Fun-first, local soccer with volunteer coaches. Teams practice once or twice a week and play their games on Saturdays.", "badge": "Practices from mid-July", "facts": [{"_key": "4e14324b", "note": "1–2× a week, set by your coach", "label": "Practices", "value": "Mid-July"}, {"_key": "3c2c3ac0", "note": "Saturdays from mid-August", "lab