", "text": "Shingle Springs"}, {"_key": "area0002", "text": "Rescue"}]}, "order": 0, "version": 1, "collection": "site"}], "about": [{"id": "about", "data": {"cta": {"text": "Explore recreational and competitive soccer with Prospector Soccer Club.", "title": "Find your place on the field", "buttons": [{"_key": "14fe972d", "href": "/recreational", "label": "Recreational soccer", "external": false}, {"_key": "9ece96ca", "href": "/competitive", "label": "Competitive soccer", "external": false}], "eyebrow": "Your next step"}, "hero": {"lead": "A community soccer club with room for every player to grow.", "chips": [{"_key": "e4534c9e", "text": "Non-profit"}, {"_key": "b06bd51d", "text": "100% volunteer-run"}, {"_key": "d41ab1fd", "text": "Cameron Park · Shingle Springs · Rescue"}], "image": {"alt": "A soccer field in the California foothills", "mediaId": "med_about"}, "title": "About Prospector", "eyebrow": "Rooted in the foothills"}, "meta": {"title": "About Prospector · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_about"}, "description": "Learn about Prospector Soccer Club: our communities, purpose, vision, mission and five core values."}, "values": {"items": [{"_key": "0ddc427a", "text": "Building trust and communication. We win and lose together.", "title": "Teamwork"}, {"_key": "db1cd063", "text": "For the game, teammates, opponents, coaches and officials.", "title": "Respect"}, {"_key": "92417ac3", "text": "Following the rules and staying committed.", "title": "Discipline"}, {"_key": "4d5b5d6e", "text": "Fair play, honesty and transparency.", "title": "Integrity"}, {"_key": "60d58276", "text": "Building lasting relationships through soccer.", "title": "Community"}], "title": "The values we play by", "eyebrow": "Our core values"}, "vision": {"body": "Every player, recreational or competitive, should have room to grow and a lasting love of the game.", "lead": "To be a cornerstone of the community: developing players at every level while championing teamwork, respect, discipline, integrity and community.", "image": {"alt": "Sunrise across a soccer pitch in the foothills", "mediaId": "med_pitch_sunrise"}, "title": "Room to grow", "eyebrow": "Looking ahead", "heading": "Our vision"}, "mission": {"image": {"alt": "A soccer field in the California foothills", "mediaId": "med_about"}, "title": "A rewarding place to play", "bullets": [{"_key": "f37ddd00", "text": "Give every player a supportive, rewarding place to play, focused on fun, enjoyment and skill at their level of interest and ability."}, {"_key": "ab421b8b", "text": "Create a challenging environment for players who want to reach their full potential."}, {"_key": "bdfddaab", "text": "Foster physical, mental and emotional growth through soccer at all ages and levels."}], "eyebrow": "What brings us together", "heading": "Our mission"}, "purpose": {"lead": "Prospector Soccer Club (PSC) serves Cameron Park, Shingle Springs and Rescue, California, in the El Dorado County foothills.", "title": "A club for our community", "eyebrow": "Our purpose", "statement": "Our purpose is to lead in developing young talent and to administer and promote an organized, non-profit, volunteer soccer program for the children of our club’s territory."}}, "order": 0, "version": 1, "collection": "about"}], "board": [{"id": "board", "data": {"hero": {"lead": "Meet the volunteers who help run Prospector Soccer Club.", "chips": [{"_key": "14d60a9b", "text": "2026 board"}, {"_key": "0faf9b81", "text": "100% volunteer-run"}, {"_key": "28debe6f", "text": "14 board roles"}], "image": {"alt": "Club volunteers gathered beside a soccer field at dusk", "mediaId": "med_board"}, "title": "Board members", "eyebrow": "Neighbors behind the club"}, "meta": {"title": "Board members · Prospector Soccer Club", "ogImage": {"alt": "", "mediaId": "med_board"}, "description": "Meet the 2026 Prospector Soccer Club board, find role contacts and find upcoming board meetings and the Annual General Meeting."}, "me